import sys

def solve(m, a, b):
    if a > b:
        a, b = b, a

    if b - a == 1:
        # If b - a = 1, all numbers from 0 to m are reachable
        return (m + 1) * (m + 2) // 2

    gcd_ab = gcd(a, b)

    if m < b:
        # Result when m < b
        reachable = set()
        for k in range(0, m + 1):
            if k % gcd_ab == 0:
                for j in range(0, m + 1 - k, a):
                    reachable.add(k + j)
        return sum(len(reachable.intersection(set(range(0, i + 1)))) for i in range(m + 1))

    # Use the fact that after a certain point, each number is reachable
    # if it satisfies the modular condition
    count = 0
    for k in range(b):
        if k % gcd_ab == 0:
            total_reachable = (m - k) // a + 1
            count += total_reachable * (total_reachable + 1) // 2

    return count

def gcd(x, y):
    while y:
        x, y = y, x % y
    return x

